body.error-page {
  min-height: 100vh;
  background-attachment: fixed;
  background-size: cover;
  color: rgba(255, 255, 255, 0.9);
  position: relative;
}

body.error-page > * {
  position: relative;
  z-index: 1;
}

body.error-page:before {
  content: "";
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 98, 255, 0.8);
}

.error-page {
  text-align: center;
  height: calc(100vh - 120px);
  display: flex;
  align-items: center;
  justify-content: center;
}

.error-page .error-page-item {
  font-size: 12rem;
  line-height: 14rem;
  margin-left: -2rem;
  text-shadow: -5px 1px 0px #0058e6;
}

.error-page .error-page-item:nth-child(2) {
  transform: translate(0, 10px);
  display: inline-block;
}

.form-control,
.swal-modal input.swal-content__input,
.custom-select {
  font-size: 0.875rem;
  border-color: #e1e1e1;
  border-radius: 0.25rem;
  background: none;
}

.form-control:focus,
.swal-modal input.swal-content__input:focus,
.custom-select:focus {
  box-shadow: none;
  border-color: rgba(0, 98, 255, 0.8);
  background: none;
}

.form-control:not(.form-control-lg):not(.form-control-sm),
.swal-modal input.swal-content__input:not(.form-control-lg):not(.form-control-sm) {
  height: calc(1.5em + .75rem + 3px);
}

.form-rounded {
  border-radius: 50px;
}

.form-control-lg {
  font-size: 1.1rem;
}

.form-control-sm {
  font-size: 0.8rem;
}

.input-group-text {
  border: none;
}

.valid-feedback {
  color: #3dd598;
}

.invalid-feedback {
  color: #fc5a5a;
}

textarea {
  min-height: 100px;
  max-height: 500px;
}

.custom-file-input:focus ~ .custom-file-label {
